#include <gtest/gtest.h>

#include <cstddef>
#include <cstdint>

extern "C" {
#include "core/data_structures/bitset.h"
}

#if defined(__has_feature)
#if __has_feature(address_sanitizer)
#define HAS_ASAN 1
#endif
#elif defined(__SANITIZE_ADDRESS__)
#define HAS_ASAN 1
#endif

#ifdef HAS_ASAN
extern "C" const char *__asan_default_options() {
    // Allows malloc to return NULL on huge allocations instead of crashing
    return "allocator_may_return_null=1";
}
#endif

namespace {

// --- Creation and Destruction Tests ---

TEST(BitsetTest, MemRequiredSanity) {
    size_t mem_100 = BitsetMemRequired(100);
    size_t mem_1000 = BitsetMemRequired(1000);

    EXPECT_GT(mem_100, 0) << "Memory required should be strictly positive.";
    EXPECT_LE(mem_100, mem_1000)
        << "Larger bitsets should require equal or more memory.";
}

TEST(BitsetTest, MemRequiredZeroBits) {
    size_t mem = BitsetMemRequired(0);

    EXPECT_GE(mem, 0) << "Memory required should be non-negative.";
}

TEST(BitsetTest, CreateAndDestroy) {
    Bitset *bs = BitsetCreate(100);
    EXPECT_NE(bs, nullptr)
        << "BitsetCreate should return a valid pointer for size 100.";
    BitsetDestroy(bs);

    // The API documentation states Destroy does nothing if bs is NULL
    BitsetDestroy(nullptr);
}

TEST(BitsetTest, CreateZeroBits) {
    Bitset *bs = BitsetCreate(0);
    EXPECT_NE(bs, nullptr)
        << "BitsetCreate should return a valid pointer even for size 0.";
    BitsetDestroy(bs);
}

#ifndef GAMESMAN_TSAN_ENABLED
// This test triggers a NULL return from malloc and should be disabled when TSan
// is in use.
TEST(BitsetTest, CreateOutOfMemory) {
    Bitset *bs = BitsetCreate(INT64_MAX);
    EXPECT_EQ(bs, nullptr)
        << "BitsetCreate should return NULL if there's not enough memory";
    if (bs) {
        BitsetDestroy(bs);
    }
}
#endif  // GAMESMAN_TSAN_ENABLED

// --- State Modification and Retrieval Tests ---

TEST(BitsetTest, InitialStateIsZero) {
    const int64_t num_bits = 64;
    Bitset *bs = BitsetCreate(num_bits);
    ASSERT_NE(bs, nullptr);

    // Ensure all bits are initially set to 0
    for (int64_t i = 0; i < num_bits; ++i) {
        EXPECT_FALSE(BitsetTest(bs, i));
    }

    // The count of set bits should be exactly 0
    EXPECT_EQ(BitsetCount(bs), 0);

    BitsetDestroy(bs);
}

TEST(BitsetTest, SetBit) {
    Bitset *bs = BitsetCreate(10);
    ASSERT_NE(bs, nullptr);

    // Setting a bit should return its previous value (false)
    EXPECT_FALSE(BitsetSet(bs, 3));

    // Testing the bit should now return true
    EXPECT_TRUE(BitsetTest(bs, 3));

    // Setting it again should return the previous value (true)
    EXPECT_TRUE(BitsetSet(bs, 3));

    // Count should reflect a single set bit
    EXPECT_EQ(BitsetCount(bs), 1);

    BitsetDestroy(bs);
}

TEST(BitsetTest, ResetBit) {
    Bitset *bs = BitsetCreate(10);
    ASSERT_NE(bs, nullptr);

    BitsetSet(bs, 5);
    EXPECT_TRUE(BitsetTest(bs, 5));

    // Resetting should return the previous value (true)
    EXPECT_TRUE(BitsetReset(bs, 5));

    // Testing should now return false
    EXPECT_FALSE(BitsetTest(bs, 5));

    // Resetting again should return the previous value (false)
    EXPECT_FALSE(BitsetReset(bs, 5));

    BitsetDestroy(bs);
}

TEST(BitsetTest, SetToSpecificValue) {
    Bitset *bs = BitsetCreate(10);
    ASSERT_NE(bs, nullptr);

    // Set bit 2 to true
    EXPECT_FALSE(BitsetSetTo(bs, 2, true));  // Returns old val (false)
    EXPECT_TRUE(BitsetTest(bs, 2));

    // Set bit 2 to false
    EXPECT_TRUE(BitsetSetTo(bs, 2, false));  // Returns old val (true)
    EXPECT_FALSE(BitsetTest(bs, 2));

    BitsetDestroy(bs);
}

TEST(BitsetTest, CountAccuracy) {
    Bitset *bs = BitsetCreate(128);
    ASSERT_NE(bs, nullptr);

    BitsetSet(bs, 0);
    BitsetSet(bs, 63);
    BitsetSet(bs, 127);

    EXPECT_EQ(BitsetCount(bs), 3);

    BitsetReset(bs, 63);
    EXPECT_EQ(BitsetCount(bs), 2);

    BitsetDestroy(bs);
}

// --- BitSetGetSerializedSize Tests ---

TEST(BitsetTest, SerializationSizeIsGreaterThanZeroForPositiveLengthBitsets) {
    Bitset *bs = BitsetCreate(42);
    ASSERT_NE(bs, nullptr);

    size_t size = BitSetGetSerializedSize(bs);
    EXPECT_GT(size, 0) << "Serialized size should be larger than 0 bytes.";

    BitsetDestroy(bs);
}

TEST(BitsetTest, SerializationSizeIsZeroForNullInputs) {
    size_t size = BitSetGetSerializedSize(nullptr);
    EXPECT_EQ(size, 0) << "Serialized size should be 0 for NULL inputs.";
}

// --- BitsetGetRawData Tests ---

TEST(BitsetTest, GetRawDataShouldReturnNonNullForValidBitsets) {
    Bitset *bs = BitsetCreate(42);
    ASSERT_NE(bs, nullptr);

    void *raw_data = BitsetGetRawData(bs);
    EXPECT_NE(raw_data, nullptr)
        << "Raw data pointer should not be null for a valid Bitset.";

    BitsetDestroy(bs);
}

TEST(BitsetTest, GetRawDataShouldReturnNullForNullInput) {
    EXPECT_EQ(BitsetGetRawData(nullptr), nullptr)
        << "Raw data pointer for NULL Bitset should be NULL.";
}
}  // namespace
